SELECT u.id AS userId, u.type, u.login_id, u.fullname, u.gender, u.birthday, u.mobile, u.email, u.address, u.profile_img, u.session_id, u.auto_login_limit, u. wrong_password_count, sd.position, sd.hire_date, sd.leave_date, GROUP_CONCAT(c.id) AS courseIdList, GROUP_CONCAT(c.is_in_progress) AS courseIsInProgressList, GROUP_CONCAT(c.name) AS courseNameList, GROUP_CONCAT(c.number_of_learner) AS courseNumberOfLearnerList, GROUP_CONCAT(c.start_date) AS courseStartDateList, GROUP_CONCAT(c.end_date) AS courseEndDateList FROM user u INNER JOIN staff_detail sd ON u.id = sd.user_id LEFT JOIN staff_assignment sa ON u.id = sa.user_id LEFT JOIN course c ON sa.course_id = c.id WHERE EXISTS ( SELECT 1 FROM staff_detail WHERE user_id = #{base.loginUserId})
AND u.type = #{page.staffType}
AND sd.position = #{page.staffPosition}
AND sd.leave_date IS NOT NULL
AND sd.leave_date IS NULL
AND u.fullname like concat('%', #{page.keyword}, '%')
AND u.id = #{page.staffId}
GROUP BY u.id ORDER BY u.${page.orderBy} ${page.orderDirection}
LIMIT #{page.offset}, #{page.pageSize}

SELECT u.id AS userId, u.type, u.login_id, u.fullname, u.gender, u.birthday, u.mobile, u.email, u.address, u.profile_img, u.session_id, u.auto_login_limit, u. wrong_password_count, sd.position, sd.hire_date, sd.leave_date, GROUP_CONCAT(c.id) AS courseIdList, GROUP_CONCAT(c.is_in_progress) AS courseIsInProgressList, GROUP_CONCAT(c.name) AS courseNameList, GROUP_CONCAT(c.number_of_learner) AS courseNumberOfLearnerList, GROUP_CONCAT(c.start_date) AS courseStartDateList, GROUP_CONCAT(c.end_date) AS courseEndDateList FROM user u INNER JOIN staff_detail sd ON u.id = sd.user_id LEFT JOIN staff_assignment sa ON u.id = sa.user_id LEFT JOIN course c ON sa.course_id = c.id WHERE EXISTS ( SELECT 1 FROM staff_detail WHERE user_id = #{base.loginUserId})
AND u.type = #{page.staffType}
AND sd.position = #{page.staffPosition}
AND sd.leave_date IS NULL
AND u.fullname like concat('%', #{page.keyword}, '%')
AND u.id = #{page.staffId}
GROUP BY u.id ORDER BY u.${page.orderBy} ${page.orderDirection}
LIMIT #{page.offset}, #{page.pageSize}

