UPDATE classroom SET
name = #{classroom.name}, primary_admin_id = #{classroom.primaryAdminId}, secondary_admin_id = #{classroom.secondaryAdminId}
WHERE
EXISTS (
  SELECT 1 FROM user
  WHERE id = #{base.loginUserId}
  AND type = 'ADMINISTRATOR')
AND
  id = #{classroom.id}

UPDATE staff_detail

  SET leave_date = NULL


  SET leave_date = #{leaveDate}

WHERE user_id = #{staffId}
